import React, { useState, useEffect, useCallback } from "react";
import axios from "axios";
import Navbar from "../components/Navbar";
import { useLocation } from "react-router-dom";

function Feedback() {

  const location = useLocation();

  // ✅ Get event details from navigation
  const eventId = location?.state?.eventId || null;
  const eventName = location?.state?.eventName || "College Event";

  // ✅ Get logged-in user from localStorage
  const user = JSON.parse(localStorage.getItem("user"));

  const userId = user?.id || null;
  const userName = user?.name || "User";

  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState("");
  const [feedbacks, setFeedbacks] = useState([]);
  const [loading, setLoading] = useState(false);

  /* =========================
     LOAD FEEDBACKS
  ========================= */

  const loadFeedbacks = useCallback(async () => {
    if (!eventId) return;

    try {
      setLoading(true);

      const res = await axios.get(
        `http://localhost:5000/feedback/${eventId}`
      );

      setFeedbacks(Array.isArray(res.data) ? res.data : []);

    } catch (error) {
      console.error("Error loading feedback:", error);
    } finally {
      setLoading(false);
    }
  }, [eventId]);

  useEffect(() => {
    loadFeedbacks();
  }, [loadFeedbacks]);

  /* =========================
     SUBMIT FEEDBACK
  ========================= */

  const submitFeedback = async () => {

    if (!userId) {
      alert("User not logged in");
      return;
    }

    if (!eventId) {
      alert("Invalid event");
      return;
    }

    if (!comment.trim()) {
      alert("Please enter a comment");
      return;
    }

    try {

      const res = await axios.post(
        "http://localhost:5000/feedback",
        {
          user_id: userId,
          user_name: userName,
          event_id: eventId,
          rating: rating,
          comment: comment
        }
      );

      if (res.data.success) {

        alert("✅ Feedback submitted");

        setComment("");
        setRating(5);

        loadFeedbacks();

      } else {
        alert("❌ Failed to submit feedback");
      }

    } catch (error) {
      console.error("Submit feedback error:", error);
      alert("Server error while submitting feedback");
    }

  };

  return (

    <div>

      <Navbar />

      <div style={{
        padding: "20px",
        maxWidth: "600px",
        margin: "auto"
      }}>

        <h2>Feedback for {eventName}</h2>

        {/* ✅ Auto-filled user */}
        <p><b>User:</b> {userName}</p>

        {/* Rating */}
        <div style={{ marginBottom: "10px" }}>
          <label>Rating: </label>

          <select
            value={rating}
            onChange={(e) => setRating(Number(e.target.value))}
          >
            <option value="1">1 ⭐</option>
            <option value="2">2 ⭐</option>
            <option value="3">3 ⭐</option>
            <option value="4">4 ⭐</option>
            <option value="5">5 ⭐</option>
          </select>
        </div>

        {/* Comment */}
        <div style={{ marginBottom: "10px" }}>
          <label>Comment</label>

          <textarea
            style={{
              width: "100%",
              height: "80px",
              padding: "8px"
            }}
            placeholder="Write your feedback..."
            value={comment}
            onChange={(e) => setComment(e.target.value)}
          />
        </div>

        <button
          onClick={submitFeedback}
          style={{
            padding: "10px 20px",
            cursor: "pointer"
          }}
        >
          Submit Feedback
        </button>

        <hr />

        <h3>All Feedback</h3>

        {loading && <p>Loading feedback...</p>}

        {!loading && feedbacks.length === 0 && (
          <p>No feedback available.</p>
        )}

        {!loading && feedbacks.map((f) => (

          <div
            key={f.id}
            style={{
              border: "1px solid #ccc",
              padding: "10px",
              marginBottom: "10px"
            }}
          >

            <p>
              <b>{f.user_name || "User"}</b> rated ⭐ {f.rating}/5
            </p>

            <p>{f.comment}</p>

            <p style={{
              fontSize: "12px",
              color: "gray"
            }}>
              {f.created_at
                ? new Date(f.created_at).toLocaleString()
                : ""}
            </p>

          </div>

        ))}

      </div>

    </div>

  );
}

export default Feedback;
